212:     /**********************************************************
213:      */
214: 
215:     /* 07-Nov-2014, tatu: When investigating [databind#604], realized that it makes
216:      *   sense to also mark this is cachable, since lookup not exactly free, and
217:      *   since it's not uncommon to "read anything"
218:      */
219:     @Override
220:     public boolean isCachable() {
221:         // 26-Mar-2015, tatu: With respect to [databind#735], there are concerns over
222:         //   cachability. It seems like we SHOULD be safe here; but just in case there
223:         //   are problems with false sharing, this may need to be revisited.
224:         return true;
225:     }
226: 
227:     @Override // since 2.12
228:     public LogicalType logicalType() {
229:         return LogicalType.Untyped;
230:     }
231: 
232:     @Override // since 2.9
233:     public Boolean supportsUpdate(DeserializationConfig config) {
234:         // 21-Apr-2017, tatu: Bit tricky... some values, yes. So let's say "dunno"
235:         return null;
236:     }
237: 
238:     @Override
239:     public Object deserialize(JsonParser p, DeserializationContext ctxt) throws IOException
240:     {
241:         switch (p.currentTokenId()) {
242:         case JsonTokenId.ID_START_OBJECT:
243:         case JsonTokenId.ID_FIELD_NAME:
244:             // 28-Oct-2015, tatu: [databind#989] We may also be given END_OBJECT (similar to FIELD_NAME),
245:             //    if caller has advanced to the first token of Object, but for empty Object
246:         case JsonTokenId.ID_END_OBJECT:
247:             if (_mapDeserializer != null) {
248:                 return _mapDeserializer.deserialize(p, ctxt);
249:             }
250:             return mapObject(p, ctxt);
251:         case JsonTokenId.ID_START_ARRAY:
252:             if (ctxt.isEnabled(DeserializationFeature.USE_JAVA_ARRAY_FOR_JSON_ARRAY)) {
253:                 return mapArrayToArray(p, ctxt);
254:             }
255:             if (_listDeserializer != null) {
256:                 return _listDeserializer.deserialize(p, ctxt);
257:             }
258:             return mapArray(p, ctxt);
259:         case JsonTokenId.ID_EMBEDDED_OBJECT:
260:             return p.getEmbeddedObject();
261:         case JsonTokenId.ID_STRING:
262:             if (_stringDeserializer != null) {
263:                 return _stringDeserializer.deserialize(p, ctxt);
264:             }
265:             return p.getText();
266: 
267:         case JsonTokenId.ID_NUMBER_INT:
268:             if (_numberDeserializer != null) {
269:                 return _numberDeserializer.deserialize(p, ctxt);
270:             }
271:             // Caller may want to get all integral values returned as {@link java.math.BigInteger},
272:             // or {@link java.lang.Long} for consistency
273:             if (ctxt.hasSomeOfFeatures(F_MASK_INT_COERCIONS)) {
274:                 return _coerceIntegral(p, ctxt);
275:             }
276:             return p.getNumberValue(); // should be optimal, whatever it is
277: 
278:         case JsonTokenId.ID_NUMBER_FLOAT:
279:             if (_numberDeserializer != null) {
280:                 return _numberDeserializer.deserialize(p, ctxt);
281:             }
282:             // Need to allow overriding the behavior regarding which type to use
283:             if (ctxt.isEnabled(DeserializationFeature.USE_BIG_DECIMAL_FOR_FLOATS)) {
284:                 return p.getDecimalValue();
285:             }
286:             // as per [databind#1453] should not assume Double but:
287:             return p.getNumberValue();
288: 
289:         case JsonTokenId.ID_TRUE:
290:             return Boolean.TRUE;
291:         case JsonTokenId.ID_FALSE:
292:             return Boolean.FALSE;
293: 
294:         case JsonTokenId.ID_NULL: // 08-Nov-2016, tatu: yes, occurs
295:             return null;
296: 
297: //        case JsonTokenId.ID_END_ARRAY: // invalid
298:         default:
299:         }
300:         return ctxt.handleUnexpectedToken(Object.class, p);
301:     }
302: 
303:     @Override
304:     public Object deserializeWithType(JsonParser p, DeserializationContext ctxt,
305:             TypeDeserializer typeDeserializer) throws IOException
306:     {
307:         switch (p.currentTokenId()) {
308:         // First: does it look like we had type id wrapping of some kind?
309:         case JsonTokenId.ID_START_ARRAY:
310:         case JsonTokenId.ID_START_OBJECT:
311:         case JsonTokenId.ID_FIELD_NAME:
312:             // Output can be as JSON Object, Array or scalar: no way to know at this point:
313:             return typeDeserializer.deserializeTypedFromAny(p, ctxt);
314: 
315:         case JsonTokenId.ID_EMBEDDED_OBJECT:
316:             return p.getEmbeddedObject();
317: 
318:         // Otherwise we probably got a "native" type (ones that map
319:         // naturally and thus do not need or use type ids)
320:         case JsonTokenId.ID_STRING:
